DO $$
<<migrate_root_id_command_webhooks>>
DECLARE 
    parentid_exist boolean := false;
BEGIN
SELECT count(*) != 0 INTO parentid_exist
    FROM information_schema.columns
    WHERE table_name = 'commandwebhooks'
    AND table_schema = current_schema()
